INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (13048, 27902, 'tt0409011', NULL, 'Love Wrecked', 'Love Wrecked', 'movie', 2005, 'https://image.tmdb.org/t/p/w500/inCHWvO1EVXa2SYYaBLavL9KkjR.jpg', 'https://image.tmdb.org/t/p/original/rBys943zqj2ZjZ2oWhFA3FW4uev.jpg', '18-year-old Jenny Taylor is ecstatic when she finds out that her favorite rock star, Jason Masters, is a guest at the tropical resort where she is working for the summer. When they are both thrown overboard during a Caribbean cruise, she saves his life and they find themselves stranded on a remote beach. Deliriously in love with the idea of time alone with him, she manages to hide the fact that they''re a stone''s throw away from their resort.', NULL, NULL, 5.4875, 5.2, 0, 1.02, '2026-09-01 03:44:37', '2026-09-01 03:44:37');
