INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (13050, 43018, 'tt0054923', NULL, 'Gidget Goes Hawaiian', 'Gidget Goes Hawaiian', 'movie', 1961, 'https://image.tmdb.org/t/p/w500/9iVh5W5TU9VN5Ky6mUuXtIaSVzt.jpg', 'https://image.tmdb.org/t/p/original/pbUyFmuw6sqZAQek5tJee3pMHUM.jpg', 'Francis is desperate: her parents want to force her to come with them on vacation to Hawaii - just during the two weeks when her beloved "Moondoggy" is home from College. When he suggests her to go for it, she''s even more in panic - doesn''t he care to be with her? So she sets out for Hawaii in the worst mood. On the plane she meets the sociable Abby, who gives her the advice to forget about Jeff - and regrets it shortly after, when Francis follows the advice and steals her boyfriend Eddie, a famous dancer. But then Jeff discovers he''s missing Francis...', NULL, NULL, 1.9577, 5.0, 0, 1.01, '2026-09-01 03:44:37', '2026-09-01 03:44:37');
