INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (13090, NULL, NULL, 250616, 'Helldivers 2', 'Helldivers 2', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coabbf.jpg', NULL, 'Helldivers 2 is a cooperative third-person shooter in which squads of up to four players are deployed from orbit onto hostile planets to complete strategic missions. Players select loadouts of weapons, armor, and stratagems that allow them to call in orbital strikes, supply drops, vehicles, and turrets during combat. Friendly fire is always active, requiring coordination between teammates. The game features a persistent galactic war where community-wide performance determines which planets are liberated or lost.', 'https://www.igdb.com/games/helldivers-2', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, NULL, 0, 6.52, '2026-09-01 03:44:37', '2026-09-01 03:44:37');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (13091, 48660, 'tt0091343', NULL, 'The Kindred', 'The Kindred', 'movie', 1987, 'https://image.tmdb.org/t/p/w500/bDMUr5IQWAwUpFZFFxltLuAIb7N.jpg', 'https://image.tmdb.org/t/p/original/kYZNaF79kwGb8RceJV7Q2EifKJG.jpg', 'Amanda''s deathbed request to her son, John, was for him to destroy all the lab notes etc. from her last experiment. She also blurts out he had a brother. At the funeral John meets Melissa, who claims to be his mother''s biggest fan. Together with some of John''s friends they go to Amanda''s house, but none are prepared for what they find there.', NULL, NULL, 2.144, 6.062, 0, 6.01, '2026-09-01 03:44:37', '2026-09-01 03:44:37');
