INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (13093, 28370, 'tt0092834', NULL, 'Date with an Angel', 'Date with an Angel', 'movie', 1987, 'https://image.tmdb.org/t/p/w500/g9CjIIyZdCybuCRkn4Ad8uWBclu.jpg', 'https://image.tmdb.org/t/p/original/A9sGtL2mvcQNDhNaNPPYP91wjqJ.jpg', 'Aspiring composer Jim Sanders is engaged to spoiled rich girl Patty. But the morning after his bachelor party, Jim wakes up to discover a beautiful, broken-winged angel in his pool. When everyone finds out about his heavenly houseguest, Jim must cope with a dangerously jealous fiancée, an exploitive future father-in-law and a group of buddies with an outrageous business plan!', NULL, NULL, 2.6678, 6.754, 0, 1.01, '2026-09-01 03:44:37', '2026-09-01 03:44:37');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (13094, 42776, 'tt0203895', NULL, 'Sea Prince and the Fire Child', 'シリウスの伝説', 'movie', 1981, 'https://image.tmdb.org/t/p/w500/1AjvCcszj5cvZQjsK2R5dYKww1j.jpg', 'https://image.tmdb.org/t/p/original/obSA6QXKWwmaljLKxf60FxtsGo1.jpg', 'The God of Water and the Goddess of Fire, who once lived in harmony, were torn apart by the Lord of the Winds. Their children, Sirius, heir to the Water Kingdom, and Malta, heir to the Fire Kingdom, become aware of the existence of their other worlds and fall in love. Their parents, however, disapprove, leading to a tale of star-crossed lovers trapped between life and death, water and fire.', NULL, NULL, 1.3573, 6.158, 0, 1.01, '2026-09-01 03:44:37', '2026-09-01 03:44:37');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (13095, 125464, 'tt0182015', NULL, 'A Cosmic Christmas', 'A Cosmic Christmas', 'movie', 1977, 'https://image.tmdb.org/t/p/w500/HEHGkQM1dIep8JURqfHNYIn2O9.jpg', 'https://image.tmdb.org/t/p/original/jC4XcnhVGl1yEOIidbipoVIPNIW.jpg', 'Three aliens from an unknown planet, who bear a strong resemblance to the Biblical Magi, visit earth to know the true meaning of Christmas. Peter, a young boy, and Lucy, his goose, are the first to encounter them. Unable to find the true meaning of Christmas in town, Peter takes them to his family''s house in the woods. While Peter''s grandmother tells the aliens about her memories of Christmas, Marvin, one of the town''s bullies, steals Lucy. In the chase to rescue Lucy, Marvin falls through the ice in a lake. Peter attempts to rescue him but falls into the lake as well. The townsfolk, who were out searching for the aliens, attempt to save the boys but their human chain isn''t long enough to reach them. The three aliens, who had sworn not to interfere with events on earth, decide to help in order to learn the meaning of Christmas.', NULL, NULL, 0.9548, 5.818, 0, 1.01, '2026-09-01 03:44:37', '2026-09-01 03:44:37');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (13096, 62892, 'tt0100356', NULL, 'Peter in Magicland', 'Peterchens Mondfahrt', 'movie', 1990, 'https://image.tmdb.org/t/p/w500/ksks3BKxqgpdbvWBqx24XSvVFLx.jpg', 'https://image.tmdb.org/t/p/original/aMs5p1tHQlgCtQJxANitpjMewpz.jpg', 'After Sumsemann the beetle loses one of his arms to a troll, he invites brother and sister Peterchen and Annaliese to join him on a journey to the moon in a quest to retrieve his lost arm.', NULL, NULL, 1.2957, 7.219, 0, 1.01, '2026-09-01 03:44:37', '2026-09-01 03:44:37');
