INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (13116, 12382, 'tt0361226', NULL, 'Portal', 'Portal', 'tv', 2002, NULL, NULL, 'Portal is a former TV show that aired on G4. During its two-season run from 2002–2004, it was one of the most popular shows on the network. Written, produced, and hosted by Dave Meinstein, Portal was in many ways a comedy, a soap opera, a skit comedy show, and a news show. It was an attempt at a new type of show by blending satire, stylistic elements, and various levels of dramatism. Portal was the first television series to use machinima.', NULL, NULL, 4.3409, 6.5, 0, 1.01, '2026-09-01 03:44:37', '2026-09-01 03:44:37');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (13117, 636514, 'tt10327842', NULL, 'Portals', 'Portals', 'movie', 2019, 'https://image.tmdb.org/t/p/w500/rqJhdpyu8s9CPSqNEXlfBubROgU.jpg', 'https://image.tmdb.org/t/p/original/6iA2Qv0jng4Dnhyyc8FB8CekdD7.jpg', 'A series of worldwide blackouts cause millions of mysterious cosmic anomalies to appear everywhere across the planet. Some people are drawn into them with horrifying consequences.', NULL, NULL, 1.9892, 3.79, 0, 1.03, '2026-09-01 03:44:37', '2026-09-01 03:44:37');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (13118, NULL, NULL, 100186, 'Destiny', 'Destiny', 'game', 1996, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8ijk.jpg', NULL, 'The player is in charge of bringing a small group of prehistoric people through the changing world, from the first crude working with stone tools to space travel, developing them from a simple tribe into a successful modern society. Along the way the player races against up to seven other tribes, all reaching for the same goal. As the player progresses through the game, he must lead his tribe to victory using diplomacy and conquest. Options include real-time or turn-based play, traditional 2D or new 3D views, full campaigns or mini-scenarios, and military or scientific victory conditions.', 'https://www.igdb.com/games/destiny--1', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 1.01, '2026-09-01 03:44:37', '2026-09-01 03:44:37');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (13119, 290999, 'tt2535470', NULL, 'Wyrmwood: Road of the Dead', 'Wyrmwood: Road of the Dead', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/8UYcvCYMFRYFzmW1LVm3S9RGCfN.jpg', 'https://image.tmdb.org/t/p/original/AihIoAQMD8GjIkKVfU22CNgYaz2.jpg', 'Barry is a talented mechanic and family man whose life is torn apart on the eve of a zombie apocalypse. His sister, Brooke, is kidnapped by a sinister team of gas-mask wearing soldiers and experimented on by a psychotic doctor. While Brooke plans her escape Barry goes out on the road to find her and teams up with Benny, a fellow survivor – together they must arm themselves and prepare to battle their way through hordes of flesh-eating monsters in a harsh Australian bushland.', NULL, NULL, 2.5147, 6.066, 0, 9.59, '2026-09-01 03:44:37', '2026-09-01 03:44:37');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (13120, 83223, 'tt0086176', NULL, 'Rats: Night of Terror', 'Rats - Notte di terrore', 'movie', 1984, 'https://image.tmdb.org/t/p/w500/aa2pwEECMyKDjaGwTfpBhLR8TKL.jpg', 'https://image.tmdb.org/t/p/original/rJJPtDRiglOMrGkclhQg64hYjey.jpg', 'One hundred years after a nuclear war has devastated the planet, society has been reborn into two factions; the underground society and the scavangers above in the wastelands. A group of scavangers on bikes come across a town infested with flesh eating rats, and soon the gore is spilling everywhere.', NULL, NULL, 1.832, 4.772, 0, 6.05, '2026-09-01 03:44:37', '2026-09-01 03:44:37');
