INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (13122, 17137, 'tt0384683', NULL, 'What We Do Is Secret', 'What We Do Is Secret', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/3ZsIq3gg5oW7TZwey9xbqYpjyBc.jpg', 'https://image.tmdb.org/t/p/original/wGrlPGwCcbmaJnxyGOAJISIjvqn.jpg', 'The true-life story of Darby Crash, who became an L.A. punk icon with his band The Germs. Along with Lorna Doom, Pat Smear, and Don Bolles, Darby Crash completely transformed the L.A. punk scene, while sacrificing everyone he loved, his career, and ultimately his life.', NULL, NULL, 1.3357, 5.155, 0, 12.03, '2026-09-01 03:44:37', '2026-09-01 03:44:37');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (13123, 42082, 'tt0198307', NULL, 'Another State of Mind', 'Another State of Mind', 'movie', 1984, 'https://image.tmdb.org/t/p/w500/x5XlkFS9D8tIg7yaihxgFBoFo5w.jpg', NULL, 'Another State of Mind is a documentary film made in the summer of 1982 chronicling the adventure (and misadventure) of two punk bands – Social Distortion and Youth Brigade – as they embark on their first international tour. Along the way they meet up with another progressive punk band, Minor Threat, whom they hang out with at the Dischord house for about a week near the end of their ill-fated tour.', NULL, NULL, 0.8223, 6.147, 0, 11.03, '2026-09-01 03:44:37', '2026-09-01 03:44:37');
