INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (13125, 25630, 'tt0790769', NULL, 'Kurt Cobain: About a Son', 'Kurt Cobain: About a Son', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/9BSHkt8VU2V22lCIewCqn4gJQVC.jpg', 'https://image.tmdb.org/t/p/original/h2wvbEKgBpALcniJ4SP4fn1MlDX.jpg', 'An intimate and moving meditation on the late musician and artist Kurt Cobain, based on more than 25 hours of previously unheard audiotaped interviews conducted with Cobain by noted music journalist Michael Azerrad for his book "Come As You Are: The Story of Nirvana." In the film, Kurt Cobain recounts his own life - from his childhood and adolescence to his days of musical discovery and later dealings with explosive fame - and offers often piercing insights into his life, music, and times. The conversations heard in the film have never before been made public, and they reveal a highly personal portrait of an artist much discussed but not particularly well understood.', NULL, NULL, 0.8152, 6.9, 0, 11.02, '2026-09-01 03:44:37', '2026-09-01 03:44:37');
