INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (13130, 38846, 'tt1263778', NULL, 'The Beautiful Person', 'La Belle Personne', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/qRMvvfrRL7VDeLOMusggY1RC8pb.jpg', 'https://image.tmdb.org/t/p/original/xxYMApIgM0LGqvaqO8cMIfFnASG.jpg', 'In the wake of her mother''s tragic death, French teenager Junie transfers to a different high school. Though Junie lives mostly inside her own head, her beauty and stoicism win her the attention of the entire male student population. Junie begins dating the gentle Otto Cleves, but finds herself intensely drawn to her youthful Italian language teacher, Nemours. When Nemours begins to reciprocate, serious complications ensue.', NULL, NULL, 2.2858, 6.5, 0, 9.02, '2026-09-01 03:44:37', '2026-09-01 03:44:37');
