INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (13135, 52717, 'tt0181912', NULL, 'In Praise of Love', 'Éloge de l''amour', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/iOeAn1yxiBypmOVHBFimjnIeqx.jpg', 'https://image.tmdb.org/t/p/original/e8qnYlw9PB1GYQa8zxetPejwZJH.jpg', 'Someone we hear talking - but whom we do not see - speaks of a project which describes the four key moments of love: meeting, physical passion, arguments/separation and making up. This project is to be told through three couples: young, adult and old. We do not know if the project is for a play, a film, a novel or an opera. The author of the project is always accompanied by a kind of servant. Meanwhile, two years earlier, an American civil servant meets with an elderly French couple who had fought in the Resistance during World War II, brokering a deal with a Hollywood director to buy the rights to tell their story. The members of the old couple''s family discuss heatedly questions of nation, memory and history.', NULL, NULL, 1.0354, 6.5, 0, 5.54, '2026-09-01 03:44:37', '2026-09-01 03:44:37');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (13136, 88042, 'tt1047540', NULL, 'Parental Guidance', 'Parental Guidance', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/815zxi87kTUvleFHjnE5SNzWmVZ.jpg', 'https://image.tmdb.org/t/p/original/6MVi1xNKVDl5ceLMfcEZ9s1KVOr.jpg', 'Artie and Diane agree to look after their three grandkids when their type-A helicopter parents need to leave town for work. Problems arise when the kids'' 21st-century behavior collides with Artie and Diane''s old-school methods.', NULL, NULL, 3.2268, 5.953, 0, 10.01, '2026-09-01 03:44:37', '2026-09-01 03:44:37');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (13137, 226751, 'tt27715627', NULL, 'Shiny Happy People', 'Shiny Happy People', 'tv', 2023, 'https://image.tmdb.org/t/p/w500/tYoh3YfEkyqQbHZ8sRtJDMPELpx.jpg', 'https://image.tmdb.org/t/p/original/44UGa0CYDfLPzFBZC5whCGripqC.jpg', 'A limited docuseries exposing the truth beneath the wholesome Americana surface of reality tv’s favorite mega-family, The Duggars, and the radical organization behind them: The Institute in Basic Life Principles. As details of the family and their scandals unfold, we realize they’re part of an insidious, much larger threat already in motion, with democracy itself in peril.', NULL, NULL, 4.5144, 7.414, 0, 10.01, '2026-09-01 03:44:37', '2026-09-01 03:44:37');
