INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (13139, 7484, 'tt0400717', NULL, 'Open Season', 'Open Season', 'movie', 2006, 'https://image.tmdb.org/t/p/w500/w5Lctmkc1yah215Luxmci4djaiW.jpg', 'https://image.tmdb.org/t/p/original/wttDKH1WRXGpebDVzrqnVSdh15u.jpg', 'Boog, a domesticated 900lb. Grizzly bear finds himself stranded in the woods 3 days before Open Season. Forced to rely on Elliot, a fast-talking mule deer, the two form an unlikely friendship and must quickly rally other forest animals if they are to form a rag-tag army against the hunters.', NULL, NULL, 6.921, 6.19, 0, 11.06, '2026-09-01 03:44:37', '2026-09-01 03:44:37');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (13140, NULL, NULL, 112257, 'Summertime Saga', 'Summertime Saga', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3dgz.jpg', NULL, 'Summertime Saga is an adult orientated high quality dating sim game, currently in development and funded wholly by Patreon backers.

Set in a small suburban town, a young man just entering college is struck by the death of his father. Mysterious circumstances surrounding the death are only the beginning of his problems as he learns that his father was in debt to a group of shady criminals.

The game features over 65 characters to meet and interact with, over 30 unique locations, 20+ mini games, with hours of new content being added every update.', 'https://www.igdb.com/games/summertime-saga', '["Linux", "Android", "PC (Microsoft Windows)", "Mac"]', NULL, NULL, 0, 9.01, '2026-09-01 03:44:37', '2026-09-01 03:44:37');
