INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (13145, 1479, 'tt0106579', NULL, 'Clean, Shaven', 'Clean, Shaven', 'movie', 1995, 'https://image.tmdb.org/t/p/w500/kpMXYy0L2GHrIVyDF0HkEiDK1Wd.jpg', 'https://image.tmdb.org/t/p/original/sL364DOfbKPNwI3BHW0KDYgc2Ti.jpg', 'Peter Winter is a young schizophrenic who is desperately trying to get his daughter back from her adoptive family. He attempts to function in a world that, for him, is filled with strange voices, electrical noise, disconcerting images, and jarringly sudden emotional shifts. During his quest, he runs afoul of the law and an ongoing murder investigation.', NULL, NULL, 1.3471, 6.5, 0, 1.03, '2026-09-01 03:44:37', '2026-09-01 03:44:37');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (13146, 16998, 'tt0428856', NULL, 'The Moustache', 'La Moustache', 'movie', 2005, 'https://image.tmdb.org/t/p/w500/4xTwprpMi7KpMukbGl21CMCz4sk.jpg', 'https://image.tmdb.org/t/p/original/cV8uAB5glyEtwIhyCK0Xr0ywnPx.jpg', 'One day, on a whim, Marc decides to shave off the moustache he''s worn all of his adult life. He waits patiently for his wife''s reaction, but neither she nor his friends seem to notice. Stranger still, when he finally tells them, they all insist he never had a moustache. Is Marc going mad? Is he the victim of some elaborate conspiracy? Or has something in the world''s order gone terribly awry?', NULL, NULL, 1.6248, 6.114, 0, 1.02, '2026-09-01 03:44:37', '2026-09-01 03:44:37');
