INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (13205, 23437, 'tt1179056', NULL, 'A Nightmare on Elm Street', 'A Nightmare on Elm Street', 'movie', 2010, 'https://image.tmdb.org/t/p/w500/nsmW28GcNabCUZfP5YtUEe8Li0f.jpg', 'https://image.tmdb.org/t/p/original/Aur8dDhjDDJBuSDa9Y9GNrvlPI5.jpg', 'Teenagers Nancy, Quentin, Kris, Jesse and Dean are all neighborhood friends who begin having the same dream of a horribly disfigured man who wears a tattered sweater and a glove made of knives. The man terrorizes them in their dreams, and the only escape is to wake up. But when, one by one, they start dying violently, the friends realize that what happens in the dream world is real, and the only way to stay alive is to stay awake.', NULL, NULL, 10.1204, 5.52, 0, 7.51, '2026-09-01 03:44:37', '2026-09-01 03:44:37');
