INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (13210, 54933, 'tt0160513', NULL, 'A Map of the World', 'A Map of the World', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/yhoXmw3zbds7gjDPJfA7CiNNssI.jpg', 'https://image.tmdb.org/t/p/original/lAIvDYjzKSqC0zbydqCk1sx6s96.jpg', 'School nurse Alice Goodwin lives with her husband and two daughters on a dairy farm in a small Wisconsin community. After an accident on her property involving a friend''s child, the town turns against her and Alice finds herself fighting charges of child abuse.', NULL, NULL, 1.7449, 6.034, 0, 11.01, '2026-09-01 03:44:37', '2026-09-01 03:44:37');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (13211, 940551, 'tt6495056', NULL, 'Migration', 'Migration', 'movie', 2023, 'https://image.tmdb.org/t/p/w500/ldfCF9RhR40mppkzmftxapaHeTo.jpg', 'https://image.tmdb.org/t/p/original/gklkxY0veMajdCiGe6ggsh07VG2.jpg', 'After a migrating duck family alights on their pond with thrilling tales of far-flung places, the Mallard family embarks on a family road trip, from New England, to New York City, to tropical Jamaica.', NULL, NULL, 17.2628, 7.358, 0, 11.02, '2026-09-01 03:44:37', '2026-09-01 03:44:37');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (13212, 5638, 'tt0064002', NULL, 'Alice''s Restaurant', 'Alice''s Restaurant', 'movie', 1969, 'https://image.tmdb.org/t/p/w500/m3xifcmDpyuYfrm1tHuACBaLjlZ.jpg', 'https://image.tmdb.org/t/p/original/gSxBpt9YVANM9NdLoVeAfZCIot6.jpg', 'After getting kicked out of college, Arlo decides to visit his friend Alice for Thanksgiving dinner. After dinner is over, Arlo volunteers to take the trash to the dump but finds it closed for the holiday, so he dumps the trash in the bottom of a ravine. This act of littering gets him arrested and sends him on a bizarre journey.', NULL, NULL, 1.6877, 6.217, 0, 11.01, '2026-09-01 03:44:37', '2026-09-01 03:44:37');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (13213, 610678, 'tt3368516', NULL, 'A Home Far Away', 'A Home Far Away', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/rsZkOHnUXvNBXy9oTCE7MqJgcT4.jpg', NULL, 'The extraordinary destiny of two people. After the Second World War, Lois is an actress in Broadway theatre, television and Hollywood films. Her husband, Edgar Snow, is world famous.  A pioneer fascinated by China, he is the first journalist to film and interview Mao Tse-tung.  Suspected by the American authorities of Communist sympathies, Ed and Lois are blacklisted.  Together with their two small children, they go to Switzerland, mid-way between China and America, where they find a new home. A story of revolution, utopia, disillusionment, and hope.', NULL, NULL, 0.9109, 7.0, 0, 11.01, '2026-09-01 03:44:37', '2026-09-01 03:44:37');
