UPDATE "recommendations" SET "tmdb_id"=57283, "imdb_id"='tt0013257', "igdb_id"=NULL, "title"='Häxan', "original_title"='Häxan', "media_type"='movie', "release_year"=1922, "poster_url"='https://image.tmdb.org/t/p/w500/3LtaPLlwlA5HX2FjqAb8lsaBI8P.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/gZwQip2KQRDNZZOEDe0Yi25tW9Z.jpg', "overview"='Grave robbing, torture, possessed nuns, and a satanic Sabbath: Benjamin Christensen''s legendary film uses a series of dramatic vignettes to explore the scientific hypothesis that the witches of the Middle Ages suffered the same hysteria as turn-of-the-century psychiatric patients. But the film itself is far from serious-- instead it''s a witches'' brew of the scary, gross, and darkly humorous.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.8673, "vote_average"=7.6, "is_ambiguous"=0, "evidence_score"=1.88894444444444431e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-09-01 03:44:37' WHERE "id"=761;
