UPDATE "recommendations" SET "tmdb_id"=790, "imdb_id"='tt0080749', "igdb_id"=NULL, "title"='The Fog', "original_title"='The Fog', "media_type"='movie', "release_year"=1980, "poster_url"='https://image.tmdb.org/t/p/w500/12EeSboRofP3CI4SPmMFNNXCbtY.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/pAOLiapALC7Q5pcCPDTA6P9pRuv.jpg', "overview"='Strange things begin to occur as a tiny California coastal town prepares to commemorate its centenary. Inanimate objects spring eerily to life; Rev. Malone stumbles upon a dark secret about the town''s founding; radio announcer Stevie witnesses a mystical fire; and hitchhiker Elizabeth discovers the mutilated corpse of a fisherman. Then a mysterious iridescent fog descends upon the village, and more people start to die.', "external_url"=NULL, "platforms"=NULL, "popularity"=10.0779, "vote_average"=6.74, "is_ambiguous"=0, "evidence_score"=3.72309090909090869e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-09-01 03:44:37' WHERE "id"=844;
