UPDATE "recommendations" SET "tmdb_id"=10490, "imdb_id"='tt0157503', "igdb_id"=NULL, "title"='Drop Dead Gorgeous', "original_title"='Drop Dead Gorgeous', "media_type"='movie', "release_year"=1999, "poster_url"='https://image.tmdb.org/t/p/w500/iMMvFvHhURa4cWv6CxhpwIDjme2.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/xXSDhhyC853VgF7OCDKpXKeA5Md.jpg', "overview"='In a small Minnesota town, the annual beauty pageant is being covered by a TV crew. Former winner Gladys Leeman wants to make sure her daughter follows in her footsteps; explosions, falling lights, and trailer fires prove that. As the Leemans are the richest family in town, the police are pretty relaxed about it all. Despite everything, main rival (but sweet) Amber Atkins won''t give up without a fight.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.16, "vote_average"=6.457, "is_ambiguous"=0, "evidence_score"=30.77, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-09-01 03:44:37' WHERE "id"=1041;
