UPDATE "recommendations" SET "tmdb_id"=377, "imdb_id"='tt0087800', "igdb_id"=NULL, "title"='A Nightmare on Elm Street', "original_title"='A Nightmare on Elm Street', "media_type"='movie', "release_year"=1984, "poster_url"='https://image.tmdb.org/t/p/w500/b9rMHAAKISRmIonaQd9Cccx0S4X.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/nzSjTiecdosBfwMGAdpt9CxltCI.jpg', "overview"='Teenagers in a small town are dropping like flies, apparently in the grip of mass hysteria causing their suicides. A cop''s daughter, Nancy Thompson, traces the cause to child molester Fred Krueger, who was burned alive by angry parents many years before. Krueger has now come back in the dreams of his killers'' children, claiming their lives as his revenge. Nancy and her boyfriend, Glen, must devise a plan to lure the monster out of the realm of nightmares and into the real world...', "external_url"=NULL, "platforms"=NULL, "popularity"=17.0396, "vote_average"=7.35, "is_ambiguous"=0, "evidence_score"=2.38710526315789479e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-09-01 03:44:37' WHERE "id"=1077;
