UPDATE "recommendations" SET "tmdb_id"=506069, "imdb_id"='tt35274207', "igdb_id"=NULL, "title"='Rock Milestones: Pink Floyd''s The Wall (The Ultimate Critical Review)', "original_title"='Rock Milestones: Pink Floyd''s The Wall (The Ultimate Critical Review)', "media_type"='movie', "release_year"=2007, "poster_url"='https://image.tmdb.org/t/p/w500/3yvNU4CP9L42z2fuWofUuKtC8CC.jpg', "backdrop_url"=NULL, "overview"='It is now over 25 years since the release of The Wall. Conceived by Roger Waters as an ambitious double album, a spectacular live show and a ground breaking feature film. The Wall has gone on to achieve iconic status in the history of popular music. This program draws on live performance footage of Pink Floyd and highlights from the film. Also includes extracts from archive interviews with Gerald Scarfe and Alan Parker, the director of The Wall, along with the views of a team of leading musicians and musicologists. This is the independent critical review of a milestone in popular culture, which strips away the prejudice to produce the ultimate retrospective on one of the most important and iconoclastic popular works of the twentieth century. Featuring Highlights From: • Another Brick in The Wall Part 2 • Comfortably Numb • One Of My Turns • Plus Many More!', "external_url"=NULL, "platforms"=NULL, "popularity"=1.2268, "vote_average"=6.0, "is_ambiguous"=0, "evidence_score"=7.02, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-09-01 03:44:37' WHERE "id"=1714;
