UPDATE "recommendations" SET "tmdb_id"=NULL, "imdb_id"=NULL, "igdb_id"=119133, "title"='Elden Ring', "original_title"='Elden Ring', "media_type"='game', "release_year"=2022, "poster_url"='https://images.igdb.com/igdb/image/upload/t_cover_big/co4jni.jpg', "backdrop_url"=NULL, "overview"='Elden Ring is an action RPG developed by FromSoftware and published by Bandai Namco Entertainment, released in February 2022. Directed by Hidetaka Miyazaki, with world-building contributions from novelist George R. R. Martin, the game features an expansive open world called the Lands Between. Players assume the role of a customisable character known as the Tarnished, who must explore this world, battle formidable enemies, and seek to restore the Elden Ring to become the Elden Lord.

The game builds on the challenging gameplay mechanics familiar from the Dark Souls series but introduces a more open-ended structure with vast exploration, dynamic weather, and a day-night cycle. It offers deep lore, complex characters, and an interconnected world filled with secrets, dungeons, and powerful bosses.', "external_url"='https://www.igdb.com/games/elden-ring', "platforms"='["Xbox Series X|S", "PlayStation 4", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', "popularity"=NULL, "vote_average"=NULL, "is_ambiguous"=0, "evidence_score"=9.11, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-09-01 03:44:37' WHERE "id"=2307;
