UPDATE "recommendations" SET "tmdb_id"=275, "imdb_id"='tt0116282', "igdb_id"=NULL, "title"='Fargo', "original_title"='Fargo', "media_type"='movie', "release_year"=1996, "poster_url"='https://image.tmdb.org/t/p/w500/rt7cpEr1uP6RTZykBFhBTcRaKvG.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/747dgDfL5d8esobk7h4odaOFhUq.jpg', "overview"='Jerry, a small-town Minnesota car salesman is bursting at the seams with debt... but he''s got a plan. He''s going to hire two thugs to kidnap his wife in a scheme to collect a hefty ransom from his wealthy father-in-law. It''s going to be a snap and nobody''s going to get hurt... until people start dying. Enter Police Chief Marge, a coffee-drinking, parka-wearing - and extremely pregnant - investigator who''ll stop at nothing to get her man. And if you think her small-time investigative skills will give the crooks a run for their ransom... you betcha!', "external_url"=NULL, "platforms"=NULL, "popularity"=10.351, "vote_average"=7.8, "is_ambiguous"=0, "evidence_score"=52.0, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-09-01 03:44:37' WHERE "id"=2700;
UPDATE "recommendations" SET "tmdb_id"=4148, "imdb_id"='tt0959337', "igdb_id"=NULL, "title"='Revolutionary Road', "original_title"='Revolutionary Road', "media_type"='movie', "release_year"=2008, "poster_url"='https://image.tmdb.org/t/p/w500/cvkD3yiVXLg3as8EAG3LaTycONQ.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/ra9aXj8PpUbUHwwTRSl5zsL6WHM.jpg', "overview"='A young couple living in a Connecticut suburb during the mid-1950s struggle to come to terms with their personal problems while trying to raise their two children. Based on a novel by Richard Yates.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.3994, "vote_average"=6.985, "is_ambiguous"=0, "evidence_score"=2.04572222222222208e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-09-01 03:44:37' WHERE "id"=2708;
UPDATE "recommendations" SET "tmdb_id"=87093, "imdb_id"='tt1126590', "igdb_id"=NULL, "title"='Big Eyes', "original_title"='Big Eyes', "media_type"='movie', "release_year"=2014, "poster_url"='https://image.tmdb.org/t/p/w500/203HAjJcLMl7xThcTqZx4zmEGcV.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/qis71iUABx2eTxN9FzOnLbnJ2OA.jpg', "overview"='In the late 1950s and early ''60s, artist Walter Keane achieves unbelievable fame and success with portraits of saucer-eyed waifs. However, no one realizes that his wife, Margaret, is the real painter behind the brush. Although Margaret is horrified to learn that Walter is passing off her work as his own, she is too meek to protest too loudly. It isn''t until the Keanes'' marriage comes to an end and a lawsuit follows that the truth finally comes to light.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.1158, "vote_average"=6.967, "is_ambiguous"=0, "evidence_score"=8.26666666666666571e+00, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-09-01 03:44:37' WHERE "id"=2713;
UPDATE "recommendations" SET "tmdb_id"=38810, "imdb_id"='tt1379182', "igdb_id"=NULL, "title"='Dogtooth', "original_title"='Κυνόδοντας', "media_type"='movie', "release_year"=2009, "poster_url"='https://image.tmdb.org/t/p/w500/cBrhzHcOxXclTItkPzsJUCTSFyl.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/b9g6LwxptKxoMqBtxrQqBml4vMb.jpg', "overview"='Three teenagers are confined to an isolated country estate that could very well be on another planet. The trio spend their days listening to endless homemade tapes that teach them a whole new vocabulary. Any word that comes from beyond their family abode is instantly assigned a new meaning. Hence ''the sea'' refers to a large armchair and ''zombies'' are little yellow flowers. Having invented a brother whom they claim to have ostracized for his disobedience, the uber-controlling parents terrorize their offspring into submission.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.5283, "vote_average"=7.036, "is_ambiguous"=0, "evidence_score"=3.21168965517241389e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-09-01 03:44:37' WHERE "id"=2714;
