UPDATE "recommendations" SET "tmdb_id"=177888, "imdb_id"='tt2325989', "igdb_id"=NULL, "title"='Teen Beach Movie', "original_title"='Teen Beach Movie', "media_type"='movie', "release_year"=2013, "poster_url"='https://image.tmdb.org/t/p/w500/sKrGe5EmDSyVaWM0uj7rJDQHRjB.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/uKoJTTgpyWiu04hzSgPWbyJfjYi.jpg', "overview"='Life''s a beach for surfers Brady and McKenzie – until a rogue wave magically transports them inside the classic ''60s beach party flick, "Wet Side Story," where a full-blown rivalry between bikers and surfers threatens to erupt. There, amidst a sea of surfing, singing and dancing, Brady and Mack accidentally change the storyline, and the film’s dreamy hero and heroine fall for them instead of for each other!', "external_url"=NULL, "platforms"=NULL, "popularity"=5.873, "vote_average"=6.911, "is_ambiguous"=0, "evidence_score"=1.11622222222222227e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-09-01 03:44:37' WHERE "id"=3455;
UPDATE "recommendations" SET "tmdb_id"=43096, "imdb_id"='tt0052847', "igdb_id"=NULL, "title"='Gidget', "original_title"='Gidget', "media_type"='movie', "release_year"=1959, "poster_url"='https://image.tmdb.org/t/p/w500/i4aRCd5sRzYLb3TLm8iiUN0iJTr.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/l1iQ1hkFYzKT2GyBIldCuJutYyM.jpg', "overview"='Due to an accident while swimming in the sea, Francis meets the surfer Moondoggie. She''s fascinated with his sport and starts to hang out with his clique. Although they make fun of her at first, they teach her to surf and soon she''s accepted and given the nickname "Gidget". But it''s hard work to become more than a friend to Moondoggie.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.2414, "vote_average"=6.0, "is_ambiguous"=0, "evidence_score"=1.21788888888888884e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-09-01 03:44:37' WHERE "id"=3457;
UPDATE "recommendations" SET "tmdb_id"=14361, "imdb_id"='tt0103924', "igdb_id"=NULL, "title"='Captain Ron', "original_title"='Captain Ron', "media_type"='movie', "release_year"=1992, "poster_url"='https://image.tmdb.org/t/p/w500/otnKFXvqFH2swlrNf2sNiXpnIsR.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/cUqa9ngoI72dFGVQKVLsTbzj65B.jpg', "overview"='When mild-mannered Martin Harvey finds out that he has inherited a vintage yacht, he decides to take his family on a Caribbean vacation to retrieve the vessel. Upon arriving on a small island and realizing that the ship is in rough shape, Martin and his family end up with more than they bargained for as the roguish Captain Ron signs on to sail the boat to Miami. It doesn''t take long before Ron''s anything-goes antics get the Harveys into plenty of trouble.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.5971, "vote_average"=5.589, "is_ambiguous"=0, "evidence_score"=20.7125, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-09-01 03:44:37' WHERE "id"=3458;
