UPDATE "recommendations" SET "tmdb_id"=1588, "imdb_id"='tt0204946', "igdb_id"=NULL, "title"='Bring It On', "original_title"='Bring It On', "media_type"='movie', "release_year"=2000, "poster_url"='https://image.tmdb.org/t/p/w500/bnVby0qI0dS7YunbShP7mw68HY3.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/3XpxR3cSQJou79KBQpPCcpZzmhj.jpg', "overview"='The Toro cheerleading squad from Rancho Carne High School in San Diego has got spirit, spunk, sass and a killer routine that''s sure to land them the national championship trophy for the sixth year in a row. But for newly-elected team captain Torrance, the Toros'' road to total cheer glory takes a shady turn when she discovers that their perfectly-choreographed routines were in fact stolen.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.0324, "vote_average"=6.3, "is_ambiguous"=0, "evidence_score"=1.66207142857142855e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-09-01 03:44:37' WHERE "id"=3503;
