UPDATE "recommendations" SET "tmdb_id"=456, "imdb_id"='tt0096697', "igdb_id"=NULL, "title"='The Simpsons', "original_title"='The Simpsons', "media_type"='tv', "release_year"=1989, "poster_url"='https://image.tmdb.org/t/p/w500/uWpG7GqfKGQqX4YMAo3nv5OrglV.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/jIArNHIekrCSVgdMbKPAXpPY03Y.jpg', "overview"='Set in Springfield, the average American town, the show focuses on the antics and everyday adventures of the Simpson family; Homer, Marge, Bart, Lisa and Maggie, as well as a virtual cast of thousands. Since the beginning, the series has been a pop culture icon, attracting hundreds of celebrities to guest star. The show has also made name for itself in its fearless satirical take on politics, media and American life in general.', "external_url"=NULL, "platforms"=NULL, "popularity"=171.4346, "vote_average"=8.0, "is_ambiguous"=0, "evidence_score"=10.93625, "created_at"='2026-07-21 03:32:24', "updated_at"='2026-09-01 03:44:37' WHERE "id"=4823;
