UPDATE "recommendations" SET "tmdb_id"=44833, "imdb_id"='tt1440129', "igdb_id"=NULL, "title"='Battleship', "original_title"='Battleship', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/9b0Im7SfedHiajTwzSL9zGyBI7M.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/85PMh0cKywekAJYDnRXfezYAmEc.jpg', "overview"='When mankind beams a radio signal into space, a reply comes from ‘Planet G’, in the form of several alien crafts that splash down in the waters off Hawaii. Lieutenant Alex Hopper is a weapons officer assigned to the USS John Paul Jones, part of an international naval coalition which becomes the world''s last hope for survival as they engage the hostile alien force of unimaginable strength. While taking on the invaders, Hopper must also try to live up to the potential that his brother, and his fiancée''s father—an Admiral—expect of him.', "external_url"=NULL, "platforms"=NULL, "popularity"=12.7245, "vote_average"=5.933, "is_ambiguous"=0, "evidence_score"=2.01, "created_at"='2026-07-30 18:28:39', "updated_at"='2026-09-01 03:44:37' WHERE "id"=6040;
