UPDATE "recommendations" SET "tmdb_id"=1999, "imdb_id"='tt0247425', "igdb_id"=NULL, "title"='In the Bedroom', "original_title"='In the Bedroom', "media_type"='movie', "release_year"=2001, "poster_url"='https://image.tmdb.org/t/p/w500/IQj11YbraLDyPYaz79jtDoAscc.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/r73OdC9TpRIknIsVyGCd5SSwplO.jpg', "overview"='Summertime on the coast of Maine, "In the Bedroom" centers on the inner dynamics of a family in transition. Matt Fowler is a doctor practicing in his native Maine and is married to New York born Ruth Fowler, a music teacher. His son is involved in a love affair with a local single mother. As the beauty of Maine''s brief and fleeting summer comes to an end, these characters find themselves in the midst of unimaginable tragedy.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.1984, "vote_average"=6.938, "is_ambiguous"=0, "evidence_score"=6.34333333333333282e+00, "created_at"='2026-07-31 03:33:23', "updated_at"='2026-09-01 03:44:37' WHERE "id"=6163;
UPDATE "recommendations" SET "tmdb_id"=11699, "imdb_id"='tt1095217', "igdb_id"=NULL, "title"='Bad Lieutenant: Port of Call New Orleans', "original_title"='Bad Lieutenant: Port of Call New Orleans', "media_type"='movie', "release_year"=2009, "poster_url"='https://image.tmdb.org/t/p/w500/zRULXsd0rb1lVfnSyQkYPi2nLcB.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/abF5X1C7KMJEJnbB7KidfHOIszj.jpg', "overview"='Terrence McDonagh is a New Orleans Police sergeant, who receives a medal and a promotion to lieutenant for heroism during Hurricane Katrina. Due to his heroic act, McDonagh injures his back and becomes addicted to prescription pain medication. He then finds himself involved with a drug dealer who is suspected of murdering a family of African immigrants.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.6267, "vote_average"=6.182, "is_ambiguous"=0, "evidence_score"=8.31428571428571494e+00, "created_at"='2026-07-31 03:33:23', "updated_at"='2026-09-01 03:44:37' WHERE "id"=6173;
