UPDATE "recommendations" SET "tmdb_id"=606, "imdb_id"='tt0089755', "igdb_id"=NULL, "title"='Out of Africa', "original_title"='Out of Africa', "media_type"='movie', "release_year"=1985, "poster_url"='https://image.tmdb.org/t/p/w500/6oMKqh08TfxmvnoFR4mm1wZB67P.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/5hCGJLTuRlD5WoscKhVPHVnD4gz.jpg', "overview"='Tells the life story of Danish author Karen Blixen, who at the beginning of the 20th century moved to Africa to build a new life for herself. The film is based on her 1937 autobiographical novel.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.3586, "vote_average"=7.152, "is_ambiguous"=0, "evidence_score"=1.18757142857142845e+01, "created_at"='2026-07-31 03:33:23', "updated_at"='2026-09-01 03:44:37' WHERE "id"=6186;
UPDATE "recommendations" SET "tmdb_id"=232672, "imdb_id"='tt1086772', "igdb_id"=NULL, "title"='Blended', "original_title"='Blended', "media_type"='movie', "release_year"=2014, "poster_url"='https://image.tmdb.org/t/p/w500/o2YrH9jS7CAfWjETHFeL0tth79E.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/g5haoqEqt5VwVwQKEkoXY9zqSxb.jpg', "overview"='Recently divorced mom Lauren and widowed dad Jim let their friends push them into a blind date, which goes disastrously wrong. Unsurprisingly, neither wants to see the other ever again. However, fate intervenes when both Jim and Lauren, unbeknownst to each other, purchase one-half of the same vacation package at a South African resort for families, during spring break. They and their children are forced to share the same romantic suite and participate in a slew of family activities together.', "external_url"=NULL, "platforms"=NULL, "popularity"=10.3427, "vote_average"=6.897, "is_ambiguous"=0, "evidence_score"=13.2625, "created_at"='2026-07-31 03:33:23', "updated_at"='2026-09-01 03:44:37' WHERE "id"=6191;
UPDATE "recommendations" SET "tmdb_id"=37585, "imdb_id"='tt0089206', "igdb_id"=NULL, "title"='Night on the Galactic Railroad', "original_title"='銀河鉄道の夜', "media_type"='movie', "release_year"=1985, "poster_url"='https://image.tmdb.org/t/p/w500/lhuPBTDmQzFCK7ZkWeIzrFY4dXL.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/oHroNlwL1bkxaw4I1uM3hL1ERsO.jpg', "overview"='Giovanni currently lives a dreary life of near non-stop work. At school, his peers ridicule him incessantly, and his employer at work is distant and cold. As his isolation from society becomes unbearable, he suddenly finds himself on a train heading far away from his miserable home. Accompanied by Campanella, an acquaintance from school, Giovanni embarks on a journey that will define the rest of his life.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.568, "vote_average"=7.163, "is_ambiguous"=0, "evidence_score"=9.06222222222222306e+00, "created_at"='2026-07-31 03:33:23', "updated_at"='2026-09-01 03:44:37' WHERE "id"=6201;
UPDATE "recommendations" SET "tmdb_id"=6068, "imdb_id"='tt0120828', "igdb_id"=NULL, "title"='Six Days Seven Nights', "original_title"='Six Days Seven Nights', "media_type"='movie', "release_year"=1998, "poster_url"='https://image.tmdb.org/t/p/w500/fzWrrCzRa16v51TXAUuT6Wendw7.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/hgzoUvscb0iQ2M3xaNiBzxG8Ors.jpg', "overview"='In the South Pacific, in Polynesia, on the island of Makatea, Quinn Harris, a taciturn pilot, leads a quiet life, content to earn a living by transporting goods in his De Havilland Beaver. His life is exactly as he wants it to be—until he meets Robin Monroe, a sophisticated and determined woman, the assistant editor of a New York magazine, on vacation for a week with her boyfriend, Frank Martin.  An urgent work assignment in Tahiti, the neighboring island, forces Robin to reluctantly hire Quinn to fly her there. But a violent storm forces them to make an emergency landing on a deserted island. This unlikely pair avoids each other at first, until they are forced to team up to escape the island... and evade the pirates who are after them. Danger and temptation are never far away...', "external_url"=NULL, "platforms"=NULL, "popularity"=4.4533, "vote_average"=6.11, "is_ambiguous"=0, "evidence_score"=6.39, "created_at"='2026-07-31 03:33:23', "updated_at"='2026-09-01 03:44:37' WHERE "id"=6208;
