UPDATE "recommendations" SET "tmdb_id"=NULL, "imdb_id"=NULL, "igdb_id"=62151, "title"='Life Is Strange 2', "original_title"='Life Is Strange 2', "media_type"='game', "release_year"=2018, "poster_url"='https://images.igdb.com/igdb/image/upload/t_cover_big/co1r7p.jpg', "backdrop_url"=NULL, "overview"='Life Is Strange 2 is an episodic adventure game played from a third-person perspective. Players control Sean Diaz, a teenager on the run with his younger brother Daniel after a tragic incident forces them to flee their home in Seattle. The game uses a road trip structure inspired by films like Into the Wild and Stand By Me, with each episode set in a new location along the US West Coast. Sean must make choices that affect both the story''s branching paths and Daniel''s developing morality and behavior. The game explores themes of family, brotherhood, and contemporary social issues through its narrative-driven gameplay.', "external_url"='https://www.igdb.com/games/life-is-strange-2', "platforms"='["PlayStation 4", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox One", "Nintendo Switch"]', "popularity"=NULL, "vote_average"=NULL, "is_ambiguous"=0, "evidence_score"=7.024, "created_at"='2026-08-04 03:20:13', "updated_at"='2026-09-01 03:44:37' WHERE "id"=7277;
