UPDATE "recommendations" SET "tmdb_id"=239678, "imdb_id"='tt1371150', "igdb_id"=NULL, "title"='This Is Where I Leave You', "original_title"='This Is Where I Leave You', "media_type"='movie', "release_year"=2014, "poster_url"='https://image.tmdb.org/t/p/w500/rVUI2267FdetVWz9UBQbqTmRVhQ.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/njK3bfEYuqwjs8YTkpaDtkoTmVr.jpg', "overview"='When their father passes away, four grown, world-weary siblings return to their childhood home and are requested -- with an admonition -- to stay there together for a week, along with their free-speaking mother and a collection of spouses, exes and might-have-beens. As the brothers and sisters re-examine their shared history and the status of each tattered relationship among those who know and love them best, they reconnect in hysterically funny and emotionally significant ways.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.4467, "vote_average"=6.642, "is_ambiguous"=0, "evidence_score"=6.51500000000000056e+00, "created_at"='2026-08-05 03:13:48', "updated_at"='2026-09-01 03:44:37' WHERE "id"=7557;
