UPDATE "recommendations" SET "tmdb_id"=2767, "imdb_id"='tt0101318', "igdb_id"=NULL, "title"='The Lovers on the Bridge', "original_title"='Les Amants du Pont-Neuf', "media_type"='movie', "release_year"=1991, "poster_url"='https://image.tmdb.org/t/p/w500/un81oln6mAv66sqnkgPSpWONUqP.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/6vWdQxx4yqV5kEeAqtzBHndo3Eg.jpg', "overview"='Set against Paris'' oldest bridge, the Pont Neuf, while it was closed for repairs, this film is a love story between two young vagrants: Alex, a would be circus performer addicted to alcohol and sedatives and Michele, a painter driven to a life on the streets because of a failed relationship and an affliction which is slowly turning her blind.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.6518, "vote_average"=7.4, "is_ambiguous"=0, "evidence_score"=12.15, "created_at"='2026-08-06 03:21:20', "updated_at"='2026-09-01 03:44:37' WHERE "id"=7615;
