UPDATE "recommendations" SET "tmdb_id"=101519, "imdb_id"='tt2006040', "igdb_id"=NULL, "title"='A Fantastic Fear of Everything', "original_title"='A Fantastic Fear of Everything', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/sMZyKSo8b47VW1h2zjjGUZIefV1.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/mUWjBk12lY0om9iEFK8wdhxj7It.jpg', "overview"='Jack is a children''s author turned crime novelist whose detailed research into the lives of Victorian serial killers has turned him into a paranoid wreck, persecuted by the irrational fear of being murdered. When Jack is thrown a life-line by his long-suffering agent and a mysterious Hollywood executive takes a sudden and inexplicable interest in his script, what should be his big break rapidly turns into his big breakdown, as Jack is forced to confront his worst demons; among them his love life, his laundry and the origin of all fear.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.928, "vote_average"=5.639, "is_ambiguous"=0, "evidence_score"=3.03, "created_at"='2026-08-07 03:39:39', "updated_at"='2026-09-01 03:44:37' WHERE "id"=8019;
