UPDATE "recommendations" SET "tmdb_id"=NULL, "imdb_id"=NULL, "igdb_id"=19817, "title"='Scorn', "original_title"='Scorn', "media_type"='game', "release_year"=2022, "poster_url"='https://images.igdb.com/igdb/image/upload/t_cover_big/co4v5c.jpg', "backdrop_url"=NULL, "overview"='Scorn is an atmospheric first person horror adventure game set in a nightmarish universe of odd forms and somber tapestry. It is designed around an idea of "being thrown into the world". Isolated and lost inside this dream-like world you will explore different interconnected regions in a non-linear fashion. The unsettling environment is a character itself. Every location contains its own theme (story), puzzles and characters that are integral in creating a cohesive lived in world. Throughout the game you will open up new areas, acquire different skill sets, weapons, various items and try to comprehend the sights presented to you.', "external_url"='https://www.igdb.com/games/scorn', "platforms"='["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', "popularity"=NULL, "vote_average"=NULL, "is_ambiguous"=0, "evidence_score"=7.51, "created_at"='2026-08-18 01:44:45', "updated_at"='2026-09-01 03:44:37' WHERE "id"=10187;
