UPDATE "recommendations" SET "tmdb_id"=39272, "imdb_id"='tt1843230', "igdb_id"=NULL, "title"='Once Upon a Time', "original_title"='Once Upon a Time', "media_type"='tv', "release_year"=2011, "poster_url"='https://image.tmdb.org/t/p/w500/u95scYysMZvBoekSLmMNJjeqXcY.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/nSJvwZziYaGMbftSDQqQ5GIb47a.jpg', "overview"='There is a town in Maine where every story book character you''ve ever known is trapped between two worlds, victims of a powerful curse. Only one knows the truth and only one can break the spell.', "external_url"=NULL, "platforms"=NULL, "popularity"=72.6091, "vote_average"=7.4, "is_ambiguous"=0, "evidence_score"=9.83800000000000096e+00, "created_at"='2026-08-18 01:44:45', "updated_at"='2026-09-01 03:44:37' WHERE "id"=10316;
UPDATE "recommendations" SET "tmdb_id"=9775, "imdb_id"='tt0376800', "igdb_id"=NULL, "title"='November', "original_title"='Noviembre', "media_type"='movie', "release_year"=2003, "poster_url"='https://image.tmdb.org/t/p/w500/6K52ZhGL1XfD4Ds33WZIYHFpNum.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/hgXhCeW8feM89W1hQGPRQV1HLNA.jpg', "overview"='Impelled by a spirit which still preserves a patina of idealism, Alfredo arrives to Madrid with the intention to create "a performance that is free, straight from the heart, capable of making people feel alive". His concept of what acting should be begins beyond the stage, out in the streets face to face with the public. Outdoors, in any town square, in a park or in the city''s most commercial street, Alfredo and his troupe November start the show; demons to provoke passers-by, displays of social conscience, actions taken to the extreme to put the forces of law and order on full alert. There are no limits, no censorship; only ideas which are always valid so long as the public ceases to be the public and becomes part of the show swept by surprise, fear, tears or laughter. Theater as life, life as theater… there is no longer any difference.', "external_url"=NULL, "platforms"=NULL, "popularity"=0.882, "vote_average"=7.068, "is_ambiguous"=0, "evidence_score"=3.01, "created_at"='2026-08-18 01:44:45', "updated_at"='2026-09-01 03:44:37' WHERE "id"=10421;
