UPDATE "recommendations" SET "tmdb_id"=1132704, "imdb_id"='tt2050645', "igdb_id"=NULL, "title"='The Mirror Mask', "original_title"='The Mirror Mask', "media_type"='movie', "release_year"=NULL, "poster_url"=NULL, "backdrop_url"=NULL, "overview"='The Mirror Mask was created as a commission for the 2005 Contour Biennial of Video Art and was originally exhibited in a multi-channel format with drawings. The feature-length edit was made simultaneously. Working from the Biennial’s theme of feminine power, the video’s exploration uses symbols from both Flemish and Egyptian art reinterpreted through CGI, latex sculptures and low-tech animation programs – the images of the past translated onto a frozen computerized canvas.', "external_url"=NULL, "platforms"=NULL, "popularity"=0.4288, "vote_average"=0.0, "is_ambiguous"=0, "evidence_score"=7.12142857142857099e+00, "created_at"='2026-08-20 01:43:50', "updated_at"='2026-09-01 03:44:37' WHERE "id"=10795;
