UPDATE "recommendations" SET "tmdb_id"=29912, "imdb_id"='tt0046247', "igdb_id"=NULL, "title"='The Robe', "original_title"='The Robe', "media_type"='movie', "release_year"=1953, "poster_url"='https://image.tmdb.org/t/p/w500/qFYZNGzftIM8dqGMJBToGraAFJp.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/nWCcl7iY718qikjbYfERstvcBrn.jpg', "overview"='Drunk and disillusioned Roman, Marcellus Gallio, wins Jesus'' robe in a dice game after the crucifixion. Marcellus has never been a man of faith like his slave, Demetrius, but when Demetrius escapes with the robe, Marcellus experiences disturbing visions and feels guilty for his actions. Convinced that destroying the robe will cure him, Marcellus sets out to find Demetrius — and discovers his Christian faith along the way.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.2517, "vote_average"=6.819, "is_ambiguous"=0, "evidence_score"=3.01333333333333319e+00, "created_at"='2026-08-25 01:38:26', "updated_at"='2026-09-01 03:44:37' WHERE "id"=11981;
