UPDATE "recommendations" SET "tmdb_id"=62676, "imdb_id"='tt0164085', "igdb_id"=NULL, "title"='Limbo', "original_title"='Limbo', "media_type"='movie', "release_year"=1999, "poster_url"='https://image.tmdb.org/t/p/w500/1ytI3G3dT6j888ySOwYhpJHz8ED.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/vKzYoegE3Zr4a3PVx8GVyPKavPb.jpg', "overview"='Traumatized by a fishing boat accident many years before, Joe Gastineau has given up his hopes for a life beyond the odd jobs he takes to support himself. That quickly changes when nomadic club singer Donna de Angelo and her troubled teen-age daughter enter Joe’s life. Both mother and daughter fall for Joe, increasing the friction between them. The tension continues to build when Joe invites them on a pleasure cruise up the Alaskan coast, discovering too late that the trip may cost them their lives.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.8792, "vote_average"=6.612, "is_ambiguous"=0, "evidence_score"=9.26, "created_at"='2026-08-26 01:43:46', "updated_at"='2026-09-01 03:44:37' WHERE "id"=12146;
